'use strict';
const financeKinds={budget:'Rubrica do orçamento',invoice:'Nota fiscal / compra',payment:'Pagamento comprovado',income:'Recebimento comprovado',bank_statement:'Extrato bancário',delivery:'Entrega / patrimônio',issue:'Pendência de conferência',project:'Identificação do projeto'};
const financeMoney=n=>n===null||n===undefined?'Não informado':new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL'}).format(n/100);
function financeTable(headers,rows){const wrap=el('div',undefined,{class:'finance-table-wrap',tabindex:'0'}),t=el('table'),head=el('thead'),hr=el('tr'),body=el('tbody');headers.forEach(h=>hr.append(el('th',h,{scope:'col'})));head.append(hr);for(const cells of rows){const tr=el('tr');for(const c of cells){const td=el('td');if(c instanceof Node)td.append(c);else td.textContent=c??'';tr.append(td)}body.append(tr)}t.append(head,body);wrap.append(t);return wrap}
async function loadFinance(){
 const result=await api('/finance');if(me?.role!=='admin'||!$('finance-content'))return;const box=$('finance-content'),{records,documents,totals}=result;box.replaceChildren();
 box.append(el('p','Arquivo privado de compras, pagamentos e conferências. Os registros preservam versões e documentos originais. Conferência documental não equivale à aprovação da prestação de contas pela SEEL.'));
 const summary=el('dl',undefined,{class:'finance-totals'});for(const [label,value]of [['Orçamento transcrito',totals.budget_cents],['Notas atuais para conferência',totals.invoice_cents],['Pagamentos com comprovantes',totals.payment_cents],['Saldo bancário conciliado',null]]){summary.append(el('dt',label),el('dd',financeMoney(value)))}box.append(summary);
 box.append(el('p','Saldo bancário indisponível: faltam extratos completos, recebimentos e rendimentos para conciliação.',{class:'form-error'}));
 for(const [label,route,name]of [['Baixar livro financeiro CSV','/finance/ledger.csv','livro-financeiro.csv'],['Baixar dados e histórico JSON','/finance/export','financeiro-auditoria.json']]){const b=el('button',label,{type:'button',class:'secondary'});b.addEventListener('click',action(async()=>download(await api(route,{blob:true}),name)));box.append(b)}
 for(const [id,label] of [['RELATORIO-XLSX','Baixar planilha de conferência do lote inicial'],['RELATORIO-PDF','Baixar relatório de conferência do lote inicial']]){const d=documents.find(x=>x.id===id);if(d){const b=el('button',label,{type:'button',class:'secondary'});b.addEventListener('click',action(async()=>download(await api('/finance/documents/'+id,{blob:true}),d.name)));box.append(b)}}
 const project=records.find(r=>r.kind==='project');if(project)box.append(el('h3',project.data.label),el('p','Processo: '+(project.data.process||'pendente')+' · '+(project.data.beneficiary||'')),el('p',project.data.notes||''));
 const edit=r=>{const b=el('button','Conferir / revisar',{type:'button',class:'secondary'});b.addEventListener('click',()=>financeForm(box,result,r));return b};
 const invs=records.filter(r=>r.kind==='invoice'),pays=records.filter(r=>r.kind==='payment');
 box.append(el('h3','Compras e documentos fiscais'),financeTable(['Nota / fornecedor','Rubrica','Valor','Comprovantes vinculados','Classificação','Conferência'],invs.map(r=>{const paid=pays.filter(p=>p.data.invoice_id===r.id).reduce((n,p)=>n+p.data.amount_cents,0);return [r.data.number+' · '+r.data.supplier,r.data.budget_code,financeMoney(r.data.amount_cents),financeMoney(paid),r.data.disposition==='current'?'Atual — conferir documentação':'Histórica / excluída dos totais',edit(r)]})));
 box.append(el('h3','Pagamentos e recebimentos'),financeTable(['Data','Tipo','Descrição','Valor','Transação','Conferência'],records.filter(r=>['payment','income'].includes(r.kind)).map(r=>[r.data.date,financeKinds[r.kind],r.data.label,financeMoney(r.data.amount_cents),r.data.transaction_ref,edit(r)])));
 box.append(el('h3','Orçamento por rubrica'),el('p','Diferença documental = orçamento menos pagamentos registrados. Não representa dinheiro disponível.'),financeTable(['Rubrica','Descrição','Orçamento','Pagamentos','Diferença documental','Conferência'],records.filter(r=>r.kind==='budget').map(r=>{const paid=pays.filter(p=>p.data.budget_code===r.data.budget_code).reduce((n,p)=>n+p.data.amount_cents,0);return [r.data.budget_code,r.data.label,financeMoney(r.data.amount_cents),financeMoney(paid),financeMoney(r.data.amount_cents-paid),edit(r)]})));
 const issues=records.filter(r=>r.kind==='issue');box.append(el('h3','Verificação e fiscalização'),el('p','Pendências registradas: '+issues.filter(r=>r.data.status!=='resolved').length));
 for(const r of issues){const d=el('details');d.append(el('summary',(r.data.status==='resolved'?'Resolvida: ':'Pendente: ')+r.data.label),el('p',r.data.notes||''),el('p','Evidências: '+r.data.evidence_ids.join(', ')),edit(r));box.append(d)}
 const operations=records.filter(r=>['delivery','bank_statement'].includes(r.kind));if(operations.length)box.append(financeTable(['Tipo','Descrição','Data','Conferência'],operations.map(r=>[financeKinds[r.kind],r.data.label,r.data.date,edit(r)])));
 box.append(el('h3','Documentos originais e integridade'),el('p','O SHA-256 permite comparar o arquivo arquivado com o original. Não substitui a consulta de validade fiscal na SEFAZ.'));
 const ds=el('details');ds.append(el('summary',documents.length+' documentos privados'));for(const d of documents){const line=el('p'),b=el('button','Baixar original',{type:'button',class:'secondary'});b.addEventListener('click',action(async()=>download(await api('/finance/documents/'+d.id,{blob:true}),d.name)));line.append(el('strong',d.id+' · '),el('span',d.name+' · SHA-256: '+d.sha256),b);ds.append(line)}box.append(ds);
 const imp=el('details');imp.append(el('summary','Importar pacote financeiro conferido'));const form=el('form'),input=field(form,'Pacote JSON com registros e documentos','file','',{type:'file'});input.accept='.json';input.required=true;form.append(el('p','A importação preserva lançamentos existentes e recusa versões divergentes. Não aprova despesas nem executa pagamentos.'),el('button','Importar pacote privado'));form.addEventListener('submit',action(async()=>{const f=input.files[0];if(!f||f.size>11*1024*1024)throw Error('Escolha um pacote de até 11 MB.');const r=await api('/finance/import',{method:'POST',data:JSON.parse(await f.text())});await loadFinance();notice(r.created+' registros incluídos; '+r.repeated+' já existentes.')}));imp.append(form);box.append(imp);
 const hist=el('details');hist.append(el('summary','Histórico de alterações ('+result.history.length+')'));hist.append(financeTable(['Quando','Registro','Versão','Responsável','Motivo'],result.history.map(h=>[new Date(h.created_at).toLocaleString('pt-BR'),h.record_id,h.version,h.actor_email||h.actor,h.reason])));box.append(hist);
 financeVisualWorkspace(box,result);return result;
}
function financeForm(box,result,record,initial={}){
 $('finance-edit')?.remove();const panel=el('div',undefined,{id:'finance-edit'}),form=el('form');panel.append(el('h3',record?'Revisar registro (preserva a versão anterior)':'Novo registro financeiro'),form);box.prepend(panel);
 const kind=field(form,'Tipo de registro','kind',record?.kind||initial.kind||'invoice',{options:Object.fromEntries(Object.entries(financeKinds).filter(([k])=>k!=='project'))});kind.disabled=!!record;const fields=el('div');form.append(fields);const draw=()=>{fields.replaceChildren();const p=record?.data||initial,k=kind.value;const desc=field(fields,'Descrição','label',p.label||'');desc.required=true;desc.maxLength=300;
  if(['budget','invoice','payment','income'].includes(k)){const a=field(fields,'Valor em reais, sem separador de milhar (ex.: 1234,56)','amount',p.amount_cents===undefined?'':(p.amount_cents/100).toFixed(2).replace('.',','));a.required=true;a.inputMode='decimal'}
  if(k!=='budget')field(fields,'Data do documento','date',p.date||'',{type:'date'}).required=['invoice','payment','income'].includes(k);
  if(['invoice','payment'].includes(k))field(fields,'Rubrica do orçamento','budget_code',p.budget_code||'',{options:Object.fromEntries(result.records.filter(r=>r.kind==='budget').map(r=>[r.data.budget_code,r.data.budget_code+' · '+r.data.label]))}).required=true;else if(k==='budget')field(fields,'Código da rubrica (ex.: 2.1)','budget_code',p.budget_code||'').required=true;
  if(k==='invoice'){field(fields,'Fornecedor','supplier',p.supplier||'').required=true;field(fields,'CNPJ (somente números)','tax_id',p.tax_id||'');field(fields,'Número / série da nota','number',p.number||'');field(fields,'Chave NF-e (44 dígitos, se aplicável)','fiscal_key',p.fiscal_key||'');field(fields,'Classificação documental','disposition',p.disposition||'current',{options:{current:'Atual — sujeita à conferência',historical:'Histórica — não somar',excluded:'Excluída dos totais — preservar histórico'}})}
  if(k==='payment'){const pick=field(fields,'Nota vinculada','invoice_id',p.invoice_id||'',{options:Object.fromEntries(result.records.filter(r=>r.kind==='invoice'&&r.data.disposition==='current').map(r=>[r.id,r.data.number+' · '+r.data.supplier]))});pick.required=true;pick.addEventListener('change',()=>{const selected=result.records.find(r=>r.id===pick.value);if(selected)fields.querySelector('[name="budget_code"]').value=selected.data.budget_code})}
  if(['payment','income'].includes(k))field(fields,'Identificador único da transação bancária','transaction_ref',p.transaction_ref||'').required=true;
  if(k==='issue')field(fields,'Situação da pendência','status',p.status||'pending',{options:{pending:'Pendente',resolved:'Resolvida com evidência'}});
  const ev=field(fields,'Documentos vinculados (selecione um ou mais)','evidence','',{options:Object.fromEntries(result.documents.map(d=>[d.id,d.id+' · '+d.name]))});ev.multiple=true;ev.size=6;for(const o of ev.options)o.selected=p.evidence_ids?.includes(o.value)||false;const noteId='finance-notes-'+crypto.randomUUID();fields.append(el('label','Observações / divergências',{for:noteId}));const note=el('textarea',p.notes||'',{id:noteId,name:'notes',rows:'5',maxlength:'10000'});fields.append(note);field(fields,'Motivo deste registro ou revisão','reason','').required=true;
 };kind.addEventListener('change',draw);draw();form.append(el('button','Salvar registro e histórico'));const cancel=el('button','Cancelar',{type:'button',class:'secondary'});cancel.addEventListener('click',()=>panel.remove());form.append(cancel);
 form.addEventListener('submit',action(async()=>{const k=kind.value,data={...(record?.data||{})};for(const name of ['label','date','budget_code','supplier','tax_id','number','fiscal_key','disposition','invoice_id','transaction_ref','status','notes'])if(fields.querySelector('[name="'+name+'"]'))data[name]=fields.querySelector('[name="'+name+'"]').value.trim();const a=fields.querySelector('[name="amount"]');if(a){if(!/^\d+([,.]\d{1,2})?$/.test(a.value.trim()))throw Error('Informe o valor como 1234,56, sem pontos de milhar.');data.amount_cents=Math.round(Number(a.value.replace(',','.'))*100)}data.evidence_ids=Array.from(fields.querySelector('[name="evidence"]').selectedOptions).map(o=>o.value);await api('/finance/records',{method:'POST',data:{id:record?.id||crypto.randomUUID(),kind:k,data,version:record?.version||0,reason:fields.querySelector('[name="reason"]').value}});await loadFinance();notice('Registro salvo. A versão anterior foi preservada.')}));panel.scrollIntoView({block:'start'});
}
document.addEventListener('portal:loaded',()=>{if(me?.role!=='admin')return;if(!$('finance-area')){const box=el('section',undefined,{id:'finance-area'}),b=el('button','Atualizar financeiro',{type:'button',class:'secondary'});b.addEventListener('click',action(loadFinance));box.append(el('h2','Financeiro e auditoria'),b,el('div',undefined,{id:'finance-content'}));$('workspace').append(box)}action(loadFinance)()});
document.addEventListener('portal:logout',()=>$('finance-area')?.remove());
